edges = [(0,2),(0,3),(0,6),(0,7),(0,8),
         (1,2),(1,3),(1,6),(1,7),(1,8),
         (2,4),(2,5),(3,4),(3,5),(4,6),(4,7),(4,8),
         (5,6),(5,7),(5,8)]

# verify triangle-free
n = 9
adj = [set() for _ in range(n)]
for u,v in edges:
    adj[u].add(v)
    adj[v].add(u)

triangles = []
for u in range(n):
    for v in adj[u]:
        if v > u:
            for w in adj[v]:
                if w > v and w in adj[u]:
                    triangles.append((u,v,w))
print("Triangles found:", triangles)

# verify maximal: for each missing edge, adding it creates a triangle
missing = []
for u in range(n):
    for v in range(u+1, n):
        if v not in adj[u]:
            missing.append((u,v))
            # check if u and v have a common neighbor
            common = adj[u].intersection(adj[v])
            if not common:
                print("Missing edge", (u,v), "has no common neighbor -> not maximal")
print("Missing edges:", missing)
print("Maximal check passed" if all(adj[u].intersection(adj[v]) for u,v in missing) else "Failed")
